require __DIR__.'/bootstrap.php';$email=trim((string)($_GET['email']??''));$token=(string)($_GET['token']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$token==='')exit('Invalid verification link.');$s=$DB->prepare('SELECT * FROM subscribers WHERE email=? AND token_hash=?');$s->execute([$email,token_hash($token)]);$r=$s->fetch();if(!$r||strtotime($r['token_expires_at'])<time())exit('This verification link is invalid or expired.');$now=now_utc();$DB->prepare('UPDATE subscribers SET verified_at=?,updated_at=? WHERE id=?')->execute([$now,$now,$r['id']]);$session=token(48);$hash=token_hash($session);$exp=gmdate('c',time()+180*24*3600);$DB->prepare('INSERT INTO access_sessions(session_hash,email,created_at,expires_at) VALUES(?,?,?,?)')->execute([$hash,$email,$now,$exp]);setcookie(verify_cookie_name(),$session,['expires'=>time()+180*24*3600,'path'=>'/','secure'=>(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off'),'httponly'=>true,'samesite'=>'Lax']);header('Location: ../?verified=1#/home');
